const byte BUZZER_PIN = 8;
const byte BUTTON_PIN = 2;

const unsigned int notes[] = {262, 330, 392, 523, 392, 523};
const unsigned int durations[] = {160, 160, 160, 280, 160, 350};
const byte NOTE_COUNT = sizeof(notes) / sizeof(notes[0]);

void setup() {
  pinMode(BUZZER_PIN, OUTPUT);
  pinMode(BUTTON_PIN, INPUT_PULLUP);
}

void loop() {
  // INPUT_PULLUP means a pressed button reads LOW.
  if (digitalRead(BUTTON_PIN) == LOW) {
    delay(20);  // Ignore brief contact bounce.
    if (digitalRead(BUTTON_PIN) == LOW) {
      for (byte i = 0; i < NOTE_COUNT; i++) {
        tone(BUZZER_PIN, notes[i], durations[i]);
        delay(durations[i] + 50);
        noTone(BUZZER_PIN);
      }

      // Require a stable release before accepting another press.
      bool released = false;
      while (!released) {
        while (digitalRead(BUTTON_PIN) == LOW) {
          delay(5);
        }
        delay(20);
        released = (digitalRead(BUTTON_PIN) == HIGH);
      }
    }
  }
}

